"""Immutable terminal Evidence for interaction-attempt lifecycle facts."""

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING

from devtools.core.identity import Identity
from devtools.core.time import Timestamp

if TYPE_CHECKING:
    from devtools.execution.interaction_attempt import (
        InteractionAttemptId,
        InteractionAttemptOutcome,
    )


@dataclass(frozen=True, slots=True)
class EvidenceId:
    """Identify one immutable Evidence record."""

    value: Identity

    @classmethod
    def new(cls) -> EvidenceId:
        """Generate an Evidence identity."""
        return cls(Identity.new())

    @classmethod
    def parse(cls, value: str) -> EvidenceId:
        """Parse UUID text as an Evidence identity."""
        return cls(Identity.parse(value))

    def __str__(self) -> str:
        """Return canonical UUID text."""
        return str(self.value)


@dataclass(frozen=True, slots=True, kw_only=True)
class InteractionAttemptTerminalEvidence:
    """Record one immutable observation of a terminal interaction attempt."""

    id: EvidenceId
    attempt_id: InteractionAttemptId
    occurred_at: Timestamp
    observed_at: Timestamp
    outcome: InteractionAttemptOutcome

    @classmethod
    def new(
        cls,
        *,
        attempt_id: InteractionAttemptId,
        occurred_at: Timestamp,
        outcome: InteractionAttemptOutcome,
    ) -> InteractionAttemptTerminalEvidence:
        """Create a terminal record with a fresh observation identity."""
        return cls(
            id=EvidenceId.new(),
            attempt_id=attempt_id,
            occurred_at=occurred_at,
            observed_at=Timestamp.now(),
            outcome=outcome,
        )

# Copyright (c) 2026
"""Immutable retained message transcripts."""

from __future__ import annotations

from collections.abc import Iterator, Sequence
from dataclasses import dataclass
from typing import overload

from devtools.agents.conversation.message import ConversationMessage


@dataclass(frozen=True, slots=True)
class History(Sequence[ConversationMessage]):
    """Represent an immutable insertion-ordered transcript of messages.

    :ivar messages: Messages in their retained insertion order.
    """

    messages: tuple[ConversationMessage, ...] = ()

    def __len__(self) -> int:
        """Return the number of retained messages."""
        return len(self.messages)

    def __iter__(self) -> Iterator[ConversationMessage]:
        """Iterate over retained messages in insertion order."""
        return iter(self.messages)

    @overload
    def __getitem__(self, index: int) -> ConversationMessage: ...

    @overload
    def __getitem__(self, index: slice) -> History: ...

    def __getitem__(self, index: int | slice) -> ConversationMessage | History:
        """Return one message or a domain-preserving message slice."""
        if isinstance(index, slice):
            return History(messages=self.messages[index])
        return self.messages[index]

    def append(self, message: ConversationMessage) -> History:
        """Return a new history with a message appended in retained order."""
        return History(messages=(*self.messages, message))

# Copyright (c) 2026
"""Process-local diagnostic collection of interaction-attempt Evidence."""

from devtools.execution.interaction_attempt import (
    InteractionAttempt,
    InteractionAttemptId,
    InteractionAttemptOutcome,
)
from devtools.observability.evidence.protocols import EvidenceSink
from devtools.observability.evidence.terminal import (
    EvidenceId,
    InteractionAttemptTerminalEvidence,
)


class ExecutionInspector:
    """Observe attempts and construct process-local terminal Evidence."""

    __slots__ = ("_attempts_by_id", "_evidence_by_id", "_sink")

    def __init__(self, sink: EvidenceSink | None = None) -> None:
        """Create an inspector with an optional narrow Evidence sink."""
        self._attempts_by_id: dict[InteractionAttemptId, InteractionAttempt] = {}
        self._evidence_by_id: dict[EvidenceId, InteractionAttemptTerminalEvidence] = {}
        self._sink = sink

    def attempt_started(self, attempt: InteractionAttempt) -> None:
        """Retain a live attempt reference."""
        self._attempts_by_id[attempt.id] = attempt

    def attempt_finished(
        self,
        attempt: InteractionAttempt,
        outcome: InteractionAttemptOutcome,
    ) -> None:
        """Construct and retain Evidence after successful terminalization."""
        self._attempts_by_id[attempt.id] = attempt
        if attempt.completed_at is None:
            return
        evidence = InteractionAttemptTerminalEvidence.new(
            attempt_id=attempt.id,
            occurred_at=attempt.completed_at,
            outcome=outcome,
        )
        self.accept(evidence)
        if self._sink is not None:
            self._sink.accept(evidence)

    def accept(self, evidence: InteractionAttemptTerminalEvidence) -> None:
        """Retain one terminal Evidence value."""
        self._evidence_by_id.setdefault(evidence.id, evidence)

    def attempt_ids(self) -> tuple[InteractionAttemptId, ...]:
        """Return retained attempt identities."""
        return tuple(self._attempts_by_id)

    def get_attempt(
        self,
        attempt_id: InteractionAttemptId,
    ) -> InteractionAttempt | None:
        """Return one retained live attempt."""
        return self._attempts_by_id.get(attempt_id)

    def get_evidence(
