class InteractionAttemptState(StrEnum):
    """Identify current interaction-attempt lifecycle state."""

    RUNNING = "running"
    SUCCEEDED = "succeeded"
    FAILED = "failed"
    CANCELLED = "cancelled"


class InteractionAttemptStage(StrEnum):
