        return cls(
            id=InteractionAttemptId.new(),
            conversation_id=conversation_id,
            message_id=message_id,
            interaction_source=interaction_source,
            started_at=Timestamp.now(),
            state=InteractionAttemptState.RUNNING,
            completed_at=None,
